from datetime import date, timedelta
import calendar

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
_LIMIT_YEAR = 3000


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])

    def gen_daily():
        d = s
        while True:
            yield d
            d += timedelta(days=k)

    def gen_weekly():
        days = sorted({_WEEKDAYS[x] for x in parts[2].split(",")})
        monday = s - timedelta(days=s.weekday())
        week = 0
        while True:
            if week % k == 0:
                base = monday + timedelta(weeks=week)
                for wd in days:
                    d = base + timedelta(days=wd)
                    if d >= s:
                        yield d
            week += 1

    def gen_monthly_day():
        dd = int(parts[2])
        base_idx = s.year * 12 + (s.month - 1)
        m = 0
        while True:
            y, mo0 = divmod(base_idx + m, 12)
            if y > _LIMIT_YEAR:
                return
            if m % k == 0:
                n_days = calendar.monthrange(y, mo0 + 1)[1]
                day = n_days if dd == -1 else dd
                if day <= n_days:
                    d = date(y, mo0 + 1, day)
                    if d >= s:
                        yield d
            m += 1

    def gen_monthly_nth():
        nth = int(parts[2])
        wd = _WEEKDAYS[parts[3]]
        base_idx = s.year * 12 + (s.month - 1)
        m = 0
        while True:
            y, mo0 = divmod(base_idx + m, 12)
            if y > _LIMIT_YEAR:
                return
            if m % k == 0:
                n_days = calendar.monthrange(y, mo0 + 1)[1]
                if nth > 0:
                    first_wd = date(y, mo0 + 1, 1).weekday()
                    day = 1 + (wd - first_wd) % 7 + 7 * (nth - 1)
                else:
                    last_wd = date(y, mo0 + 1, n_days).weekday()
                    day = n_days - (last_wd - wd) % 7
                if 1 <= day <= n_days:
                    d = date(y, mo0 + 1, day)
                    if d >= s:
                        yield d
            m += 1

    def gen_yearly():
        mm, dd = (int(x) for x in parts[2].split("-"))
        j = 0
        while True:
            year = s.year + j
            if year > _LIMIT_YEAR:
                return
            if j % k == 0:
                try:
                    d = date(year, mm, dd)
                except ValueError:
                    d = None
                if d is not None and d >= s:
                    yield d
            j += 1

    if kind == "DAILY":
        gen = gen_daily()
    elif kind == "WEEKLY":
        gen = gen_weekly()
    elif kind == "MONTHLY" and len(parts) == 3:
        gen = gen_monthly_day()
    elif kind == "MONTHLY":
        gen = gen_monthly_nth()
    else:
        gen = gen_yearly()

    result = []
    for d in gen:
        if len(result) >= count:
            break
        result.append(d.isoformat())
    return result
